('0c99d0bb-5e68-5951-bf1b-80210b1cc024', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarê Silêmaniyê li kîjan perçeyê Kurdistanê ye?', 'Bakurê Kurdistanê', 'Rojavayê Kurdistanê', 'Rojhilatê Kurdistanê', 'Başûrê Kurdistanê', 'D', 'Silêmanî li Başûr e; di sedsala 18an de wek paytexta mîrektiya Babanan hat avakirin û navendeke edebî ya girîng e.', 'Silêmanî li Başûr e; di sedsala 18an de wek paytexta mîrektiya Babanan hat avakirin û navendeke edebî ya girîng e.', 'Silêmanî Başûr''dadır; 18. yüzyılda Baban mirliğinin merkezi olarak kurulmuş, önemli bir edebiyat merkezidir.', 3, true, 'multiple_choice', NULL, NULL, 'Erdnîgariya herêmê', 'Encyclopaedia Britannica — Kurdistan, Zagros, Lake Van; UNESCO World Heritage List (Diyarbakır Fortress and Hevsel Gardens, 2015)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cografya_0017
