('97ee714f-087c-522b-a3a9-cffe079dd2d0', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarê Mehabadê li kîjan perçeyê Kurdistanê ye?', 'Rojhilatê Kurdistanê', 'Bakurê Kurdistanê', 'Rojavayê Kurdistanê', 'Başûrê Kurdistanê', 'A', 'Mehabad li Rojhilat e; di 1946an de Komara Kurdistanê li vî bajarî hat ragihandin.', 'Mehabad li Rojhilat e; di 1946an de Komara Kurdistanê li vî bajarî hat ragihandin.', 'Mehabad Rojhilat''tadır; 1946''da Kurdistan Cumhuriyeti bu şehirde ilan edilmiştir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2175
('c929f246-1d6b-5ced-911f-1982412ac317', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarê Kobanê li kîjan perçeyê Kurdistanê ye?', 'Rojavayê Kurdistanê', 'Bakurê Kurdistanê', 'Başûrê Kurdistanê', 'Rojhilatê Kurdistanê', 'A', 'Kobanê li Rojava ye; navê wê yê din Eyn el-Ereb e û bi berxwedana 2014-2015an tê bibîranîn.', 'Kobanê li Rojava ye; navê wê yê din Eyn el-Ereb e û bi berxwedana 2014-2015an tê bibîranîn.', 'Kobanê Rojava''dadır; diğer adı Ayn el-Arab''dır ve 2014-2015 direnişiyle anılır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2354
('628edb52-164b-509c-a49e-00fa73d2db50', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarê ku bi erebî "Erbîl" tê gotin, navê wî yê kurdî çi ye?', 'Mûsil', 'Kerkûk', 'Hewlêr', 'Silêmanî', 'C', 'Hewlêr navê kurdî yê Erbîlê ye, ku navenda Herêma Kurdistanê ya Iraqê ye.', 'Hewlêr navê kurdî yê Erbîlê ye, ku navenda Herêma Kurdistanê ya Iraqê ye.', 'Hewlêr, Irak Kürdistan Bölgesi''nin merkezi Erbil''in Kürtçe adıdır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2376
('748ea447-cd15-50e6-a1b6-ca27dba0f7ab', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Herêma Hewraman di kêleka sînorê kîjan du welatan de ye?', 'Îran-Iraq', 'Iraq-Sûriye', 'Tirkiye-Sûriye', 'Îran-Tirkiye', 'A', 'Herêma Hewraman devereke kurdî ya çiyayî ye, li ser sînorê Îran û Îraqê.', 'Herêma Hewraman devereke kurdî ya çiyayî ye, li ser sînorê Îran û Îraqê.', 'Hawraman (Hewramî) bölgesi, İran ile Irak sınır kuşağında, dağlık bir Kürt yöresidir.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2467
('d25b8b16-284d-5228-ab26-bab85eb17208', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarên wek Amed, Riha û Mêrdîn li kîjan herêma dîrokî cih digirin?', 'Mezopotamyaya Jorîn', 'Çandiniya genim û ceh', 'herêma Botan/Cizîrê', 'Herêma Kurdistanê ya Iraqê', 'A', 'Ev bajar li herêma Mezopotamyaya Jorîn a di navbera Dîcle û Firatê de ne.', 'Ev bajar li herêma Mezopotamyaya Jorîn a di navbera Dîcle û Firatê de ne.', 'Bu şehirler, Dicle-Fırat arasındaki Yukarı Mezopotamya bölgesinde yer alır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2497
('dbe62c63-14c1-584f-a2be-e1bfd3472fc9', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çiyayê Sîpan" nêzîkî kîjan golê ye?', 'Gola Wanê', 'Gola Egîrdîrê', 'Gola Xwê', 'Gola Beyşehîrê', 'A', 'Sîpan çiyayekî volkanîk ê vemirî ye û li bakurê Gola Wanê bilind dibe; lewra nêzîkî vê golê ye.', 'Sîpan çiyayekî volkanîk ê vemirî ye û li bakurê Gola Wanê bilind dibe; lewra nêzîkî vê golê ye.', 'Süphan, Van Gölünün kuzeyinde yükselen sönmüş volkanik bir dağdır; bu konumundan dolayı Van Gölüne yakınlığıyla bilinir.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2705
('66f2e690-67aa-5624-b0c9-ecd26dee105e', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Navên "Cizîr û Botan" bi kîjan herêma dîrokî ve tên naskirin?', 'Hîlala Bibereket/Mezopotamya', 'Herêma Kurdistanê ya Iraqê', 'çiyayên li erdnîgariya kurdî', 'herêma Botan/Cizîrê', 'D', 'Botan navê mîrektî û herêma dîrokî ya derdora Cizîra Botan e; Cizîr jî bajarekî li qeraxa Dîcleyê ye ku navenda vê herêmê tê hesibandin.', 'Botan navê mîrektî û herêma dîrokî ya derdora Cizîra Botan e; Cizîr jî bajarekî li qeraxa Dîcleyê ye ku navenda vê herêmê tê hesibandin.', 'Botan, merkezi Cizre olan tarihî mirlik ve bölgenin adıdır; Cizre, Dicle kıyısındaki bu bölgenin merkezi sayılır.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2818
('c86835eb-006b-553e-92b5-33c55cc68d16', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Geliyê Munzurê" çi ye?', 'deşta keviran a ku ji lavên Karacadaxê pêk hatiye', 'geliyê bi statuya parka neteweyî ya li Dêrsimê', 'deşta çandiniyê ya mezin a ku bi çemikên Firatê tê avdan', 'çiyayê ku gola kraterê ya duyemîn a herî mezin a cîhanê lê ye', 'B', 'Geliyê Munzurê li Dêrsimê ye û ji ber xwezaya xwe bi statuya parka neteweyî tê parastin.', 'Geliyê Munzurê li Dêrsimê ye û ji ber xwezaya xwe bi statuya parka neteweyî tê parastin.', 'Munzur Vadisi Dersim''dedir ve doğal yapısı nedeniyle millî park statüsüyle korunur.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8149
('c6b19878-109c-5549-897a-88d3f9e00f60', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çiyayê Sîpanê" çi ye?', 'Newala ku li Dêrsimê bi statûya parka neteweyî heye', 'zozanên bilind ên ku çemeke gelek jê serê xwe digirin', 'Çiyayê volkanîk ê vemirî yê li bakurê Gola Wanê', 'deşta bereketdar a ku Cizîr û Silopiyê digire', 'C', 'Çiyayê Sîpanê li bakurê Gola Wanê ye û volkaneke vemirî ye; êdî çalak nîne.', 'Çiyayê Sîpanê li bakurê Gola Wanê ye û volkaneke vemirî ye; êdî çalak nîne.', 'Süphan Dağı Van Gölü''nün kuzeyindedir ve sönmüş bir volkandır; artık aktif değildir.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8155
('ead3706c-121c-568e-b47e-536ee5f68eb0', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Beşa Firata Jorîn li ku derê ye?', 'Deşta çandiniyê ya mezin a ku şaxên Feratê av didinê', 'Çiyayê dîrokî yê ku bawer tê kirin keştiya Nûh lê rûniştiye', 'zozanên bilind ên ku çemeke gelek jê serê xwe digirin', 'Beşê bakurrojava yê bilind ê erdnîgariya Kurdistanê', 'D', 'Ferat li vê herêmê hê di herika xwe ya jorîn de ye; ji ber ku ev der beşa bilind a bakurê rojavayê erdnîgariya Kurdistanê ye, jê re Beşa Firata Jorîn tê gotin.', 'Ferat li vê herêmê hê di herika xwe ya jorîn de ye; ji ber ku ev der beşa bilind a bakurê rojavayê erdnîgariya Kurdistanê ye, jê re Beşa Firata Jorîn tê gotin.', 'Fırat bu kesimde henüz yukarı çığırındadır; Kürdistan coğrafyasının kuzeybatısındaki yüksek kesimi kapsadığı için bu adla anılır.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8242
('b9f15100-333a-5558-8cdd-9924b371b574', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Kratera Nemrûdê" li ku / wek çi tê zanîn?', 'çiyayê ku gola kraterê ya duyemîn a herî mezin a cîhanê lê ye', 'çiyayên ku erdnîgariya Kurdistanê ji serî heta binî parçe dikin', 'çiyayê volkanîk ê nefeal ê li bakurê Gola Wanê', 'gola bendavê ya çêkirî ya li nêzî Silêmaniyê', 'A', 'Nemrûd li nêzî Tetwanê çiyayekî volkanîk ê vemirî ye; di çalika wî de goleke mezin a kraterê çêbûye û çiya bi vê taybetmendiya xwe tê nasîn.', 'Nemrûd li nêzî Tetwanê çiyayekî volkanîk ê vemirî ye; di çalika wî de goleke mezin a kraterê çêbûye û çiya bi vê taybetmendiya xwe tê nasîn.', 'Nemrut, Tatvan yakınlarında sönmüş volkanik bir dağdır; zirvesindeki çanakta büyük bir krater gölü oluşmuştur ve dağ bu özelliğiyle tanınır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8319
('eda3eb29-2408-5404-b02b-3f52f7466616', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Gola Ûrmiyeyê" çi ye?', 'çiyayê dîrokî yê ku tê bawerkirin keştiya Nuh lê daketiye', 'çemê hêrs ê ku çiyayên Colemêrgê diqelêşe', 'hewza çem a ku Amed û Şirnexê digire', 'hewza gola şor a li rojhilatê Kurdistanê', 'D', 'Gola Ûrmiyeyê li rojhilatê Kurdistanê ye û goleke şor e; ava wê nayê vexwarin.', 'Gola Ûrmiyeyê li rojhilatê Kurdistanê ye û goleke şor e; ava wê nayê vexwarin.', 'Urmiye Gölü Doğu Kürdistan''dadır ve tuzlu bir göldür; suyu içilmez.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8331
('963c5777-f5c9-5b70-b669-4c8b0c06dd42', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan wate ji bo peyva "erd" rast e?', 'Zemîn', 'Ezman', 'Derya', 'Ewr', 'A', '"erd" hem "yer" hem "toprak" tê wateyê. Mînak: Erdê vê deverê bi bereket e.', '"erd" hem "yer" hem "toprak" tê wateyê. Mînak: Erdê vê deverê bi bereket e.', '"erd" hem "yer" hem "toprak" anlamına gelir. Örnek: Bu yörenin toprağı bereketlidir.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8406
('585d04d5-4fd7-51f0-a83d-1f1d057f3904', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Gever (Yüksekova)" çi ye?', 'geliyê bi statuya parka neteweyî ya li Dêrsimê', 'deşta bi bereket a ku deştên Cizîr û Silopiyê digire', 'çemê girîng ê ku ji Êlihê derbas dibe û dirijê Dîcleyê', 'deşta tektonîk a bilind a li Colemêrgê', 'D', 'Gever deşta bilind a li Colemêrgê ye û bi çiyayan dorpêçkirî ye; loma deşteke tektonîk a bilind e.', 'Gever deşta bilind a li Colemêrgê ye û bi çiyayan dorpêçkirî ye; loma deşteke tektonîk a bilind e.', 'Gever Hakkâri''deki yüksek ovadır ve dağlarla çevrilidir; bu yüzden yüksek bir tektonik ovadır.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8479
('c33e360d-6b01-535b-9d45-cc6a5899f8f8', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Karacadax" çi ye?', 'volkana bazaltî ya berfireh a li deşta Amedê', 'beşa bilind a bakurê rojavayê erdnîgariya Kurdistanê', 'geliyê bi statuya parka neteweyî ya li Dêrsimê', 'avhewaya ku li herêmên kurdî yên nêzî Behra Spî tê dîtin', 'A', '"Qerejdax": volkana bazaltî ya berfireh a li deşta Amedê ye.', '"Qerejdax": volkana bazaltî ya berfireh a li deşta Amedê ye.', '"Karacadağ": Diyarbakır ovasında yer alan yayvan bazaltik volkan.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8480
('dc85e13a-5607-5682-b4d4-913a3e4dfb8d', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çiyayên Qendîlê" li ku ne?', 'çiyayên bilind ên li ser sînorê Îraq û Îranê', 'lûtkeya herî bilind a erdnîgariya Kurdistanê', 'girseya çiyayî ya nêzî çemê Garzanê', 'çiyayê volkanîk ê feal ê xwedî gola kraterê', 'A', 'Çiyayên Qendîlê rêzeçiyayên bilind in û li ser sînorê Iraq û Îranê dirêj dibin.', 'Çiyayên Qendîlê rêzeçiyayên bilind in û li ser sînorê Iraq û Îranê dirêj dibin.', 'Kandil Dağları yüksek sıradağlardır ve Irak ile İran sınırı boyunca uzanır.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8506
('bc8f62d2-023f-5ff9-9866-269807506092', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çemê Dîcleyê" çi ye?', 'gola tektonîk a di sînorên Elezîzê de', 'çemê ku ji bin sûrên Amedê derbas dibe', 'gola bendavê ya ku li ser çemê Diyalayê hatiye avakirin', 'rêzeçiyayên herî asê yên erdnîgariya Dêrsimê', 'B', '"Çemê Dîcleyê": çemê ku ji binê sûrên Amedê derbas dibe.', '"Çemê Dîcleyê": çemê ku ji binê sûrên Amedê derbas dibe.', '"Dicle nehri": Diyarbakır surlarının altından geçen nehir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8523
('85e345da-da12-5082-90cc-cced11451cb9', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Avhewaya Kurdistanê" çi ye?', 'hewza ku gola herî mezin a sodadar a dinyayê ye', 'zivistanên sar ên deverên bejahî û çiyayî', 'newala kanyonê ya kûr a ku Çemê Botan çêkiriye', 'Kendava Besrayê (bi ser Şet-ul Erebê ve)', 'B', '"Avhewaya Kurdistanê": li deverên parzemînî û çiyayî zivistanên sar.', '"Avhewaya Kurdistanê": li deverên parzemînî û çiyayî zivistanên sar.', '"Kürdistan iklimi": karasal ve dağlık alanlarda soğuk kışlar.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8539
('41665ecf-07e3-5ff9-8e6d-aa347103af83', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Gola Hazarê" çi ye?', 'gola tektonîk a di sînorên Elezîzê de', 'rêzeçiyayên herî asê yên erdnîgariya Dêrsimê', 'gola bendavê ya ku li ser çemê Diyalayê hatiye avakirin', 'çemê ku ji bin sûrên Amedê derbas dibe', 'A', '"Gola Hazarê": gola tektonîk a li herêma Elezîzê.', '"Gola Hazarê": gola tektonîk a li herêma Elezîzê.', '"Hazar gölü": Elazığ sınırlarında yer alan tektonik göl.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8603
('d56af306-ecb4-5cbf-8cf7-064f076410c1', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Beşa Dîcleyê" çi ye?', 'hewza çem a ku Amed û Şirnexê digire', 'bi yek ji cihên niştecihbûna berdewam a herî kevn a cîhanê bûyîna xwe', 'wek parêzgeha 19em a Iraqê statuyeke cuda bi dest xist', 'gola bendavê ya çêkirî ya li nêzî Silêmaniyê', 'A', 'Beşa Dîcleyê herêma hewza çemê Dîcleyê ye û Amed û Şirnex di nav vê hewzê de ne.', 'Beşa Dîcleyê herêma hewza çemê Dîcleyê ye û Amed û Şirnex di nav vê hewzê de ne.', 'Dicle Bölümü Dicle Nehri''nin havza bölgesidir ve Diyarbakır ile Şırnak bu havzanın içindedir.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8672
('d1372933-143c-5106-87c9-00f2c22f8926', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Peyva "hewa" bi Tirkî çi ye?', 'vadi', 'hava', 'ova', 'sınır', 'B', '"hewa" = "hava". Mînak: Di zivistanê de hewa li çiyan pir sar dibe.', '"hewa" = "hava". Mînak: Di zivistanê de hewa li çiyan pir sar dibe.', '"hewa" = "hava". Örnek: Kışın dağlarda hava çok soğur.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_8715
('1e1d5a70-f478-502d-9121-5d4f129a573a', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Çiyayê pîroz ê ku li gorî baweriyan keştiya Nûh Pêxember li ser rûniştiye, kîjan e?', 'Qerejdax', 'Heskîf', 'Çemê Firatê', 'Çiyayê Cûdî', 'D', '"Çiyayê Cûdî" tê vê wateyê: çiyayê pîroz ê ku li gorî baweriyan keştiya Nûh Pêxember li ser rûniştiye.', '"Çiyayê Cûdî" tê vê wateyê: çiyayê pîroz ê ku li gorî baweriyan keştiya Nûh Pêxember li ser rûniştiye.', '"Çiyayê Cûdî" şu anlama gelir: inanışa göre Nuh Peygamber''in gemisinin üzerine oturduğu kutsal dağ.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20826
('13f09861-251b-5ac7-8edd-b8c74a5c17a1', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Şûna herî kevn a perestgehên mirovahiyê ku li nêzîkî bajarê Rihayê ye, kîjan e?', 'Çiyayê Sîpanê', 'Newala Dîcleyê', 'Girê Mirazan', 'Çemê Firatê', 'C', '"Girê Mirazan" tê vê wateyê: şûna herî kevn a perestgehên mirovahiyê ku li nêzîkî bajarê Rihayê ye.', '"Girê Mirazan" tê vê wateyê: şûna herî kevn a perestgehên mirovahiyê ku li nêzîkî bajarê Rihayê ye.', '"Girê Mirazan" şu anlama gelir: Riha (Urfa) yakınlarındaki, insanlığın en eski tapınak yeri.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_curated_20851
('56436bfa-972e-5a5f-97e2-f3a72e45390e', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Girê Mirazan" ew bajarê kevnar û dîrokî ye ku li ser çemê Dîcleyê ye û xwedî şikeftên bêhempa ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Heskîf" e; "Girê Mirazan" şûna herî kevn a perestgehên mirovahiyê ye ku li nêzîkî bajarê Rihayê ye.', 'Na — ev ravekirina "Heskîf" e; "Girê Mirazan" şûna herî kevn a perestgehên mirovahiyê ye ku li nêzîkî bajarê Rihayê ye.', 'Hayır — bu tanım "Heskîf"e aittir; "Girê Mirazan" ise Riha (Urfa) yakınlarındaki, insanlığın en eski tapınak yeridir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_0017
('6e82e60d-f6e8-5a54-847e-cf88d1b4da28', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Geliyê Botan" geliyê teng e li başûrê Colemêrgê ku ava Zapê ya hov tê re derbas dibe.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Geliyê Zapê" ye; "Geliyê Botan" geliyê kûr e ku çemê Botanê li herêma Sêrtê di nav zinaran de vekiriye.', 'Na — ev ravekirina "Geliyê Zapê" ye; "Geliyê Botan" geliyê kûr e ku çemê Botanê li herêma Sêrtê di nav zinaran de vekiriye.', 'Hayır — bu tanım "Geliyê Zapê" kavramına aittir; "Geliyê Botan" ise Botan çayının Siirt yöresinde kayalar arasında açtığı derin vadidir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0004
('ea649690-a519-571c-b976-6d54a2bcc726', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çemê Garzanê" ew çem e ku ji çiyayên Sêrtê dadikeve û digihîje Dîcleyê.', 'Rast', 'Şaş', '-', '-', 'A', 'Garzan çemek e ku li herêma Sêrtê diherike û digihîje Dîcleyê. Çemên bi vî rengî ava çiyayan kom dikin û dibin şaxên çemên mezintir.', 'Garzan çemek e ku li herêma Sêrtê diherike û digihîje Dîcleyê. Çemên bi vî rengî ava çiyayan kom dikin û dibin şaxên çemên mezintir.', 'Garzan, Siirt yöresinden akıp Dicle''ye katılan akarsulardan biridir. Bu tür çaylar dağların suyunu toplayıp daha büyük nehirleri besler.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0009
('608b79d5-742b-50cf-aec8-8d8efa828eae', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Av" hêmana bingehîn e ku jiyanê dide û şêwaza niştecihbûnê diyar dike. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Av ji bo vexwarin, çandinî û jiyana rojane şertê bingehîn e. Ji ber vê yekê cihên nêzî avê bi gelemperî ji bo niştecihbûnê hatine bijartin.', 'Av ji bo vexwarin, çandinî û jiyana rojane şertê bingehîn e. Ji ber vê yekê cihên nêzî avê bi gelemperî ji bo niştecihbûnê hatine bijartin.', 'Su, içme, tarım ve günlük yaşam için temel şarttır. Bu yüzden suya yakın yerler genellikle yerleşim için tercih edilmiştir.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0011
('b88e9006-f8e0-5f10-a2ca-ec796c286404', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Colemêrg" bajarê çiyayî yê herî bilind ê herêmê ye ku bi zozan û geliyên xwe tê naskirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Colemêrg (Hekarî) bajarekî çiyayî ye û bi zozan, gelî û xwezaya bilind tê nasîn. Pênaseya pirsê balê dikişîne ser vê taybetmendiya çiyayî.', 'Colemêrg (Hekarî) bajarekî çiyayî ye û bi zozan, gelî û xwezaya bilind tê nasîn. Pênaseya pirsê balê dikişîne ser vê taybetmendiya çiyayî.', 'Colemêrg (Hakkâri) dağlık yapısı, yayla ve vadileriyle bilinen bir kenttir. Sorudaki tanım bu dağlık niteliği vurgular.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0015
('dc2457e3-57f6-5b4d-baa5-6c28a408dcef', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Erd" rûyê axê ye ku çandinî, niştecihbûn û jiyana rojane li ser tê avakirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Erd rûyê axê ye ku mirov li ser dijî, diçîne û avahiyan lê dike. Hemû çalakiyên çandinî û niştecihbûnê li ser vî rûyî pêk tên.', 'Erd rûyê axê ye ku mirov li ser dijî, diçîne û avahiyan lê dike. Hemû çalakiyên çandinî û niştecihbûnê li ser vî rûyî pêk tên.', 'Toprak yüzeyi, insanların üzerinde yaşadığı, ekip biçtiği ve yapı kurduğu zemindir. Tarım ve yerleşim etkinliklerinin tümü bu yüzeyde gerçekleşir.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0017
('1f778af6-26bd-56fa-80a7-3d9be482184b', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Herêma Serhedê" herêma bilind a bakur e ku Agirî, Wan û Muşê digire nav xwe. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Serhed bi gelemperî ji bo herêmên bilind ên bakur tê gotin û bajarên wek Agirî, Wan û Muşê di nav vê çarçoveyê de bi nav dibin. Ev navekî çandî û erdnîgarî ye, ne sînorekî fermî.', 'Serhed bi gelemperî ji bo herêmên bilind ên bakur tê gotin û bajarên wek Agirî, Wan û Muşê di nav vê çarçoveyê de bi nav dibin. Ev navekî çandî û erdnîgarî ye, ne sînorekî fermî.', 'Serhed genellikle kuzeydeki yüksek yöreler için kullanılır; Ağrı, Van ve Muş gibi iller bu çerçevede anılır. Bu resmî bir sınır değil kültürel-coğrafi bir bölge adıdır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0019
('a1126c6d-6702-5e47-800d-b632358f6d64', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çiya" bilindahiya erdê ye ku avhewa, çandinî û rêyên veguhastinê diyar dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Çiya bilindahiyên mezin ên erdê ne û bandorê li avhewa, çandinî û veguhastinê dikin. Her ku bilindahî zêde dibe, germahî dadikeve û şêweya jiyanê diguhere.', 'Çiya bilindahiyên mezin ên erdê ne û bandorê li avhewa, çandinî û veguhastinê dikin. Her ku bilindahî zêde dibe, germahî dadikeve û şêweya jiyanê diguhere.', 'Dağ, yeryüzünün büyük yükseltileridir; iklimi, tarımı ve ulaşımı etkiler. Yükselti arttıkça sıcaklık düşer ve yaşam biçimi değişir.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0021
('8d60bc36-ea93-5471-8445-9d28d30925ca', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Deşt" erdê rast û berdar e ku çandinî lê hêsan e.', 'Rast', 'Şaş', '-', '-', 'A', 'Deşt erdên rast û bi gelemperî berdar in. Ji ber rastbûna wan, çandinî û veguhastin li deştan hêsantir e.', 'Deşt erdên rast û bi gelemperî berdar in. Ji ber rastbûna wan, çandinî û veguhastin li deştan hêsantir e.', 'Ova düz ve genellikle verimli arazidir. Düzlüğü sayesinde tarım ve ulaşım ovalarda daha kolaydır.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0023
('0c677d25-2a59-5183-adf2-a44c6eee1706', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Daristan" ew dever e ku bi darên xurt hatiye nixumandin û avhewayê nerm dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Daristan deverên ku bi daran hatine nixumandin in. Daristan avhewayê nerm dikin, axê diparêzin û ji bo gelek zindiyan jîngeh in.', 'Daristan deverên ku bi daran hatine nixumandin in. Daristan avhewayê nerm dikin, axê diparêzin û ji bo gelek zindiyan jîngeh in.', 'Orman ağaçlarla kaplı alanlardır. Ormanlar iklimi yumuşatır, toprağı korur ve birçok canlıya yaşama ortamı sağlar.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0025
('8b9fdb5d-9f30-5652-9602-c6a5609c21d2', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Gol" ava sekinî ye ku li newalekê kom dibe û bi çeman tê xwedîkirin. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Gol ava sekinî ye ku li newal û deştên nizm kom dibe. Gol bi gelemperî bi baran û çeman tê xwedîkirin.', 'Gol ava sekinî ye ku li newal û deştên nizm kom dibe. Gol bi gelemperî bi baran û çeman tê xwedîkirin.', 'Göl, çanak ya da alçak alanlarda toplanan durgun sudur. Göller genellikle yağmur ve akarsularla beslenir.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0027
('f7cde7cd-46b3-5fb3-9c4b-4edbdbecf492', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Hewa" rewşa rojane ya atmosferê ye ku baran, ba û germahiyê digire nav xwe.', 'Rast', 'Şaş', '-', '-', 'A', 'Hewa rewşa rojane ya atmosferê ye, wek baran, ba û germahî. Ew ji avhewayê cuda ye, ji ber ku avhewa navîniya demdirêj e, hewa rewşa kurt e.', 'Hewa rewşa rojane ya atmosferê ye, wek baran, ba û germahî. Ew ji avhewayê cuda ye, ji ber ku avhewa navîniya demdirêj e, hewa rewşa kurt e.', 'Hava yağmur, rüzgâr ve sıcaklık gibi atmosferin günlük durumudur. Uzun dönem ortalaması olan iklimden farklıdır; hava kısa süreli durumu anlatır.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0029
('7c9816a8-c902-5392-ad20-225bc4e59378', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çemê Dîcleyê" ew çem e ku di nav Amedê re diherike û bi Ferat re Mezopotamyayê xwedî dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Dîcle çemekî mezin ê Mezopotamyayê ye û di nav Amedê re derbas dibe. Ew bi Ferat re herêma Mezopotamyayê av dide.', 'Dîcle çemekî mezin ê Mezopotamyayê ye û di nav Amedê re derbas dibe. Ew bi Ferat re herêma Mezopotamyayê av dide.', 'Dicle Mezopotamya''nın büyük nehirlerinden biridir ve Amed''in içinden geçer. Fırat ile birlikte Mezopotamya''yı sular.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0033
('0f70e0b3-5ed2-5902-896a-8f359c04ac38', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çemê Dîcleyê" çemê herî dirêj ê Asyaya Rojava ye ku ji çiyayên Erzeromê dertê. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Çemê Firatê" ye; "Çemê Dîcleyê" çemê ku di nav Amedê re diherike û bi Ferat re Mezopotamyayê xwedî dike ye.', 'Na — ev ravekirina "Çemê Firatê" ye; "Çemê Dîcleyê" çemê ku di nav Amedê re diherike û bi Ferat re Mezopotamyayê xwedî dike ye.', 'Hayır — bu tanım "Çemê Firatê" kavramına ait; "Çemê Dîcleyê", Amed''in içinden akıp Fırat ile Mezopotamya''yı besleyen nehirdir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0034
('352a1ef7-6f12-5589-8007-8d8790955720', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çemê Erezê" çemê ku sînorê bakurê rojhilat ê herêmê pêk tîne û diherike Deryaya Xezerê ye.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Erez çemekî dirêj ê rojhilat e û ava wê digihîje Deryaya Xezerê; li hin beşan ew dibe sînor di navbera welatan de.', 'Rast e. Erez çemekî dirêj ê rojhilat e û ava wê digihîje Deryaya Xezerê; li hin beşan ew dibe sînor di navbera welatan de.', 'Doğru. Aras, doğuda akan uzun bir nehirdir ve suyu Hazar Denizi''ne ulaşır; bazı kesimlerde ülkeler arasında sınır oluşturur.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0037
('b51dc541-e28d-5539-95d0-23b449ae0758', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çemê Erezê" çemê ku ji Botanê tê û li nêzîkî Zaxoyê digihîje Dîcleyê ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Çemê Xabûrê" ye; "Çemê Erezê" çemê ku sînorê bakurê rojhilat ê herêmê pêk tîne û diherike Deryaya Xezerê ye.', 'Na — ev ravekirina "Çemê Xabûrê" ye; "Çemê Erezê" çemê ku sînorê bakurê rojhilat ê herêmê pêk tîne û diherike Deryaya Xezerê ye.', 'Hayır — bu tanım "Çemê Xabûrê" kavramına ait; "Çemê Erezê", bölgenin kuzeydoğu sınırını çizen ve Hazar''a dökülen nehirdir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0038
('f8308d77-1732-557d-9a02-0ab0fd2e2486', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çemê Xabûrê" ava hov a ku ji Colemêrgê dadikeve û enerjiya avî ya başûr xwedî dike ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Ava Zapê" ye; "Çemê Xabûrê" çemê ku ji Botanê tê û li nêzîkî Zaxoyê digihîje Dîcleyê ye.', 'Na — ev ravekirina "Ava Zapê" ye; "Çemê Xabûrê" çemê ku ji Botanê tê û li nêzîkî Zaxoyê digihîje Dîcleyê ye.', 'Hayır — bu tanım "Ava Zapê" kavramına ait; "Çemê Xabûrê", Botan''dan gelip Zaho yakınlarında Dicle''ye karışan çaydır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0040
('f2d300b6-c37f-58c9-a47f-a676bea326b2', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: Têgeha "Ava Zapê" tê vê wateyê: ava hov a ku ji Colemêrgê dadikeve û enerjiya avî ya başûr xwedî dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Ava Zapê ji çiyayên Colemêrgê derdikeve û ber bi başûr ve bi herikîneke xurt diherike; ew şaxeke Dîcleyê ye.', 'Rast e. Ava Zapê ji çiyayên Colemêrgê derdikeve û ber bi başûr ve bi herikîneke xurt diherike; ew şaxeke Dîcleyê ye.', 'Doğru. Zap Suyu Hakkâri dağlarından doğup güneye doğru güçlü bir akışla ilerler; Dicle''nin bir koludur.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0041
('f1ce47a4-defe-5d40-8a78-5b1aeb03ead8', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Deşta Amedê" deşta bazaltî ya berdar e ku li dora Amedê belav dibe. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Deşta Amedê deşteke fireh û berdar e li dora Amedê; axa wê bi giranî ji bazalta Qerecdaxê ye, lewma ji bo çandinê guncaw e.', 'Rast e. Deşta Amedê deşteke fireh û berdar e li dora Amedê; axa wê bi giranî ji bazalta Qerecdaxê ye, lewma ji bo çandinê guncaw e.', 'Doğru. Amed Ovası, Amed çevresinde uzanan geniş ve verimli bir ovadır; toprağı büyük ölçüde Karacadağ bazaltıdır, bu yüzden tarıma elverişlidir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0043
('1e6404f1-2c4c-591a-b682-68978e693bb0', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: Têgeha "Deşta Amedê" tê vê wateyê: deşta fireh a başûr ku çandiniya genim lê serdest e.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Deşta Hewlêrê" ye; "Deşta Amedê" deşta bazaltî ya berdar e ku li dora Amedê belav dibe.', 'Na — ev ravekirina "Deşta Hewlêrê" ye; "Deşta Amedê" deşta bazaltî ya berdar e ku li dora Amedê belav dibe.', 'Hayır — bu tanım "Deşta Hewlêrê" kavramına ait; "Deşta Amedê", Amed çevresine yayılan verimli bazalt ovasıdır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0044
('9cd678da-21a4-5804-a94e-c1e9adb7c53c', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Deşta Hewlêrê" deşta ku di navbera Qerejdaxê û Firatê de dirêj dibe ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Deşta Sêwregê" ye; "Deşta Hewlêrê" deşta fireh a başûr e ku çandiniya genim lê serdest e.', 'Na — ev ravekirina "Deşta Sêwregê" ye; "Deşta Hewlêrê" deşta fireh a başûr e ku çandiniya genim lê serdest e.', 'Hayır — bu tanım "Deşta Sêwregê" kavramına ait; "Deşta Hewlêrê", buğday tarımının egemen olduğu geniş güney ovasıdır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0046
('c863fc0e-268e-5f56-af4d-31dd4d2fa279', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Karacadax" rêzeçiyayek e ku serekaniya gelek çeman e û bi zozanên xwe tê naskirin. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Çiyayên Bîngolê" ye; "Karacadax" çiyayê volkanîk ê bazaltî ye ku deşta Amedê ji ya Rihayê vediqetîne.', 'Na — ev ravekirina "Çiyayên Bîngolê" ye; "Karacadax" çiyayê volkanîk ê bazaltî ye ku deşta Amedê ji ya Rihayê vediqetîne.', 'Hayır — bu tanım "Çiyayên Bîngolê" kavramına ait; "Karacadax", Amed ovasını Urfa ovasından ayıran bazaltik volkanik dağdır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0050
('2b887352-bf5d-5a2e-80a3-3265824356cd', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Çiyayên Bîngolê" rêzeçiyayên Dêrsimê yên bi berf in ku Parka Neteweyî ya Geliyê Munzurê lê ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Çiyayên Mûnzûrê" ye; "Çiyayên Bîngolê" ew rêzeçiyayên ku serekaniya gelek çeman in û bi zozanên xwe tên naskirin in.', 'Na — ev ravekirina "Çiyayên Mûnzûrê" ye; "Çiyayên Bîngolê" ew rêzeçiyayên ku serekaniya gelek çeman in û bi zozanên xwe tên naskirin in.', 'Hayır — bu tanım "Çiyayên Mûnzûrê" kavramına ait; "Çiyayên Bîngolê", birçok nehrin kaynağı olan, yaylalarıyla bilinen sıradağlardır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0052
('95323c59-a92b-5c22-bfdd-51406bec86e9', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Geliyê Mûnzûrê" geliyê kûr e ku çemê Mûnzûrê di nav zinarên kilsî de vekiriye.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Geliyê Mûnzûrê geliyekî kûr û teng e; çemê Mûnzûrê di nav çiyayan de ev gelî kolaye û ava wê zelal û sar e.', 'Rast e. Geliyê Mûnzûrê geliyekî kûr û teng e; çemê Mûnzûrê di nav çiyayan de ev gelî kolaye û ava wê zelal û sar e.', 'Doğru. Munzur Vadisi derin ve dar bir vadidir; Munzur Çayı dağların arasında bu vadiyi oluşturur ve suyu berrak ve soğuktur.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0055
('941dac91-c66f-563a-adb1-3df963e3c499', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Çiyayê Tendûrekê" lûtkeya herî bilind a başûrê Kurdistanê ye li ser sînorê Îranê. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Çiyayê Helgurdê" ye; "Çiyayê Tendûrekê" çiyayê volkanîk ê feal e li navbera Agirî û Wanê.', 'Na — ev ravekirina "Çiyayê Helgurdê" ye; "Çiyayê Tendûrekê" çiyayê volkanîk ê feal e li navbera Agirî û Wanê.', 'Hayır — bu tanım "Çiyayê Helgurdê" kavramına ait; "Çiyayê Tendûrekê", Ağrı ile Van arasındaki aktif volkanik dağdır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0058
('9d6abc2f-05c4-5df3-8c3e-ba48dcbb2a0d', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: Têgeha "Çiyayê Helgurdê" tê vê wateyê: rêzeçiyayên mezin ên ku sînorê xwezayî yê welatê kurdan pêk tînin.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Rêzeçiyayên Zagrosê" ye; "Çiyayê Helgurdê" lûtkeya herî bilind a başûrê Kurdistanê ye li ser sînorê Îranê.', 'Na — ev ravekirina "Rêzeçiyayên Zagrosê" ye; "Çiyayê Helgurdê" lûtkeya herî bilind a başûrê Kurdistanê ye li ser sînorê Îranê.', 'Hayır — bu tanım "Rêzeçiyayên Zagrosê" kavramına ait; "Çiyayê Helgurdê", İran sınırındaki, Güney Kürdistan''ın en yüksek zirvesidir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0060
('5ea29250-2a8a-574f-a4dd-e7768bf8e76e', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Gola Dokanê" bendava li ser çemê Sîrwanê ye ku deşta Germiyanê av dide.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Gola Derbendîxanê" ye; "Gola Dokanê" bendava mezin a li ser Zapa Biçûk e ku Silêmaniyê bi av û elektrîkê xwedî dike.', 'Na — ev ravekirina "Gola Derbendîxanê" ye; "Gola Dokanê" bendava mezin a li ser Zapa Biçûk e ku Silêmaniyê bi av û elektrîkê xwedî dike.', 'Hayır — bu tanım "Gola Derbendîxanê" kavramına ait; "Gola Dokanê", Küçük Zap üzerinde, Süleymaniye''yi su ve elektrikle besleyen büyük baraj gölüdür.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0064
('48a9f9f0-3eb7-58e3-8a0b-469815b2cead', (select id from categories where name = 'Cografya'), 'ku-kmr', '"Herêma Behdînan" herêma bakurê rojava ye bi navenda Dihokê ku bi zaravayê behdînî tê naskirin. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Behdînan herêma li dora Dihokê ye û behdînî zaravayê kurmancî ye ku li wê herêmê tê axaftin; navê zaravayî ji vê herêmê tê.', 'Rast e. Behdînan herêma li dora Dihokê ye û behdînî zaravayê kurmancî ye ku li wê herêmê tê axaftin; navê zaravayî ji vê herêmê tê.', 'Doğru. Behdinan, Duhok çevresindeki bölgedir ve behdinî bu bölgede konuşulan Kurmancça ağzıdır; lehçenin adı bu bölgeden gelir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0067
('8e7e5e92-0717-513c-9ae8-a9df89dcb4f7', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Rast e an şaş e: "Avhewaya Deryaya Navîn" avhewaya bi zivistanên şil û havînên germ e ku li başûrê rojava tê dîtin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Avhewaya Deryaya Navîn bi zivistanên nerm û baranî û bi havînên germ û hişk tê naskirin; li başûrê rojava jî ev avhewa tê dîtin.', 'Rast e. Avhewaya Deryaya Navîn bi zivistanên nerm û baranî û bi havînên germ û hişk tê naskirin; li başûrê rojava jî ev avhewa tê dîtin.', 'Doğru. Akdeniz iklimi ılık ve yağışlı kışlar ile sıcak ve kurak yazlarla tanınır; güneybatıda da bu iklim görülür.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_cog_0069
('e39563de-9712-55fe-b2dd-05f2283839b1', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Çiyayê Cûdî li kîjan perçeyê Kurdistanê ye?', 'Bakurê Kurdistanê', 'Rojavayê Kurdistanê', 'Başûrê Kurdistanê', 'Rojhilatê Kurdistanê', 'A', 'Çiyayê Cûdî li herêma Şirnexê ya li Bakur e. Li gorî baweriyên herêmê keştiya Nûh Pêxember li ser vî çiyayî rûniştiye; ev bawerî di gelek çavkaniyên herêmî de tê dubarekirin.', 'Çiyayê Cûdî li herêma Şirnexê ya li Bakur e. Li gorî baweriyên herêmê keştiya Nûh Pêxember li ser vî çiyayî rûniştiye; ev bawerî di gelek çavkaniyên herêmî de tê dubarekirin.', 'Cûdî Dağı, Bakur''daki Şirnex yöresindedir. Yöre inanışına göre Nuh''un gemisi bu dağa oturmuştur; bu inanış birçok yerel kaynakta yinelenir.', 2, true, 'multiple_choice', NULL, NULL, 'Bankanın kendi onaylı tanımlarından türetildi', 'internal:restore_batch_2026_08_07 — terim tanımları editorial/offline bankalarındaki onaylı açıklamalarla aynı', 'approved', 'Kurmancî', 1, now()), -- yerel: restore_2026_08_07_0007
('86bd8c51-4bb3-5600-a05d-696d985be875', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Deşta Amedê bi kîjan taybetmendiya axa xwe ji deştên derdorê vediqete?', 'axa şor a bêber', 'axa bazaltî ya berdar', 'axa qûmî ya hişk', 'axa çiyayî ya kevirîn', 'B', 'Deşta Amedê li ser lavên bazaltî yên Karacadaxê ava bûye; ev ax berdar e û çandiniya genim li wê derê bi hêsanî tê kirin. Kevirê bazalt ê reş di avahiyên bajêr de jî tê dîtin.', 'Deşta Amedê li ser lavên bazaltî yên Karacadaxê ava bûye; ev ax berdar e û çandiniya genim li wê derê bi hêsanî tê kirin. Kevirê bazalt ê reş di avahiyên bajêr de jî tê dîtin.', 'Amed ovası Karacadağ''ın bazalt lavları üzerinde oluşmuştur; bu toprak verimlidir ve buğday tarımına elverişlidir. Siyah bazalt taşı şehrin yapılarında da görülür.', 3, true, 'multiple_choice', NULL, NULL, 'Bankanın kendi onaylı tanımlarından türetildi', 'internal:restore_batch_2026_08_07 — terim tanımları editorial/offline bankalarındaki onaylı açıklamalarla aynı', 'approved', 'Kurmancî', 1, now()), -- yerel: restore_2026_08_07_0008
('81b3abfc-a963-5074-8c52-8fd00bea1fd7', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bajarê Colemêrgê li kîjan perçeyê Kurdistanê ye?', 'Bakurê Kurdistanê', 'Rojavayê Kurdistanê', 'Başûrê Kurdistanê', 'Rojhilatê Kurdistanê', 'A', 'Colemêrg li Bakur e; ew bi çiyayên xwe yên bilind û geliyên kûr tê nasîn û yek ji herêmên herî bilind ên deverê ye.', 'Colemêrg li Bakur e; ew bi çiyayên xwe yên bilind û geliyên kûr tê nasîn û yek ji herêmên herî bilind ên deverê ye.', 'Colemêrg Bakur''dadır; yüksek dağları ve derin vadileriyle bilinir, bölgenin en yüksek yörelerinden biridir.', 2, true, 'multiple_choice', NULL, NULL, 'Bankanın kendi onaylı tanımlarından türetildi', 'internal:restore_batch_2026_08_07 — terim tanımları editorial/offline bankalarındaki onaylı açıklamalarla aynı', 'approved', 'Kurmancî', 1, now()), -- yerel: restore_2026_08_07_0014
('8bf023ed-b657-53c9-a1e7-72b2e7c3f137', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Gola Wanê li kîjan perçeyê Kurdistanê ye?', 'Rojavayê Kurdistanê', 'Başûrê Kurdistanê', 'Bakurê Kurdistanê', 'Rojhilatê Kurdistanê', 'C', 'Gola Wanê li Bakur e; ava wê sodadar e, ji ber vê yekê ne ji bo vexwarinê ne jî ji bo avdanê tê bikaranîn.', 'Gola Wanê li Bakur e; ava wê sodadar e, ji ber vê yekê ne ji bo vexwarinê ne jî ji bo avdanê tê bikaranîn.', 'Wan Gölü Bakur''dadır; suyu sodalıdır, bu yüzden ne içme ne de sulama için kullanılır.', 2, true, 'multiple_choice', NULL, NULL, 'Bankanın kendi onaylı tanımlarından türetildi', 'internal:restore_batch_2026_08_07 — terim tanımları editorial/offline bankalarındaki onaylı açıklamalarla aynı', 'approved', 'Kurmancî', 1, now()) -- yerel: restore_2026_08_07_0015
